import{_ as t,o,c as a,ag as r}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Creational Patterns — Quick Reference","description":"","frontmatter":{},"headers":[],"relativePath":"design_patterns/creational/CreationalPatternsQuickRef.md","filePath":"design_patterns/creational/CreationalPatternsQuickRef.md"}'),n={name:"design_patterns/creational/CreationalPatternsQuickRef.md"};function c(s,e,i,d,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="creational-patterns-—-quick-reference" tabindex="-1">Creational Patterns — Quick Reference <a class="header-anchor" href="#creational-patterns-—-quick-reference" aria-label="Permalink to &quot;Creational Patterns — Quick Reference&quot;">​</a></h1><p>One-paragraph mental model per pattern for fast revision. Not a tutorial — read the pattern&#39;s own <code>.md</code> for the full explanation.</p><hr><h2 id="singleton" tabindex="-1">Singleton <a class="header-anchor" href="#singleton" aria-label="Permalink to &quot;Singleton&quot;">​</a></h2><p><strong>One instance. Full stop.</strong></p><p>The whole application shares one object. The pattern controls construction so you can never accidentally create a second one. Use it for things that genuinely need to be global and shared — a config registry, a connection pool, a logger. The trap: Singleton is a hidden global; it makes testing harder and creates tight coupling across the codebase. Spring beans are singletons by default without the Singleton pattern — prefer DI over hand-rolled singletons in production.</p><p><strong>In one line:</strong> <em>Everyone gets the same object.</em></p><p><strong>JDK:</strong> <code>Runtime.getRuntime()</code>, <code>Collections.EMPTY_LIST</code></p><hr><h2 id="factory-method" tabindex="-1">Factory Method <a class="header-anchor" href="#factory-method" aria-label="Permalink to &quot;Factory Method&quot;">​</a></h2><p><strong>The caller wants a product. It doesn&#39;t care which one.</strong></p><p>The caller says &quot;give me a developer&quot; and gets back an <code>Employee</code>. It never writes <code>new AndroidDeveloper()</code> — it just calls <code>hireForTeam()</code> on whatever hiring process it was given. You swap the product by swapping the creator subclass. The creator (the hiring process) decides what gets built; the caller (HR) only sees the abstract product. Extend the system by adding a new creator + product pair — no existing class changes.</p><p><strong>In one line:</strong> <em>Caller gets a product; a subclass decides which one.</em></p><p><strong>JDK:</strong> <code>Calendar.getInstance()</code>, <code>NumberFormat.getInstance()</code></p><hr><h2 id="abstract-factory" tabindex="-1">Abstract Factory <a class="header-anchor" href="#abstract-factory" aria-label="Permalink to &quot;Abstract Factory&quot;">​</a></h2><p><strong>Factory Method, but for a whole matched family of products.</strong></p><p>You don&#39;t just need one product — you need several that belong together. A cheap furniture factory produces a <code>CheapChair</code> and a <code>CheapSofa</code> that match. A luxury factory produces <code>LuxuryChair</code> + <code>LuxurySofa</code>. The factory interface guarantees you can never accidentally mix a luxury chair with a cheap sofa. The client gets the whole family from one factory call site and works only against the abstract product interfaces. Add a new family by adding a new concrete factory — no existing client code changes.</p><p><strong>In one line:</strong> <em>Caller gets a coordinated family of products; the factory guarantees they match.</em></p><p><strong>JDK:</strong> JDBC <code>Connection</code> → <code>Statement</code> → <code>ResultSet</code> from the same driver; <code>DocumentBuilderFactory</code></p><hr><h2 id="builder" tabindex="-1">Builder <a class="header-anchor" href="#builder" aria-label="Permalink to &quot;Builder&quot;">​</a></h2><p><strong>Construct complex objects step by step, hand back an immutable result.</strong></p><p>When an object has many fields — some required, many optional — constructors become unreadable (<code>new Job(title, city, null, null, 0, true, false)</code>). Builder separates construction from representation: required fields go into the builder&#39;s constructor (so you can never forget them), optional fields are fluent setters, and <code>build()</code> validates before handing back a fully constructed, immutable product. The Director variant adds pre-packaged recipes so the same steps can build completely different products.</p><p><strong>In one line:</strong> <em>Construction is complex; Builder makes it readable and validates before handing you the result.</em></p><p><strong>JDK:</strong> <code>StringBuilder</code>, <code>HttpRequest.newBuilder()</code>, <code>Stream.Builder</code>; Lombok <code>@Builder</code> in any Spring project</p><hr><h2 id="static-factory-methods-effective-java-item-1-—-not-a-gof-pattern" tabindex="-1">Static Factory Methods <em>(Effective Java Item 1 — not a GoF pattern)</em> <a class="header-anchor" href="#static-factory-methods-effective-java-item-1-—-not-a-gof-pattern" aria-label="Permalink to &quot;Static Factory Methods *(Effective Java Item 1 — not a GoF pattern)*&quot;">​</a></h2><p><strong>Named constructors with superpowers.</strong></p><p>Instead of <code>new Temperature(37, CELSIUS)</code> you write <code>Temperature.celsius(37)</code>. The name is clearer, you can cache instances (return the same object for the same input), and you can return a subtype the caller doesn&#39;t even know about. The two limitations: you can&#39;t subclass a class whose only constructor is private, and static factory methods don&#39;t stand out in Javadoc the way constructors do.</p><p><strong>In one line:</strong> <em>Give construction a meaningful name; optionally cache or hide the concrete type.</em></p><p><strong>JDK:</strong> <code>List.of(...)</code>, <code>Optional.empty()</code>, <code>Integer.valueOf(5)</code>, <code>Path.of(...)</code></p><hr><h2 id="prototype" tabindex="-1">Prototype <a class="header-anchor" href="#prototype" aria-label="Permalink to &quot;Prototype&quot;">​</a></h2><p><strong>Copy a pre-built object instead of constructing from scratch.</strong></p><p>When construction is expensive (database lookup, heavy computation) and you already have a fully configured instance, cloning it is faster than building a new one. The prototype is a template — you copy it and tweak the copy. Java&#39;s <code>Cloneable</code>/<code>clone()</code> is the canonical mechanism but is widely considered broken (shallow copy by default, no constructor called, awkward exception). Copy constructors are the modern alternative: <code>new Shape(existingShape)</code> gives you full control over what gets copied and how deeply.</p><p><strong>In one line:</strong> <em>Construction is expensive; copy a ready-made template instead.</em></p><p><strong>JDK:</strong> <code>new ArrayList&lt;&gt;(existingList)</code>, <code>new HashMap&lt;&gt;(existingMap)</code> — copy constructors everywhere</p><hr><h2 id="shallow-copy-vs-deep-copy-applies-to-prototype" tabindex="-1">Shallow copy vs deep copy (applies to Prototype) <a class="header-anchor" href="#shallow-copy-vs-deep-copy-applies-to-prototype" aria-label="Permalink to &quot;Shallow copy vs deep copy (applies to Prototype)&quot;">​</a></h2><ul><li><strong>Shallow copy:</strong> the new object gets its own primitive fields but shares references to any nested objects with the original. Mutating a nested object in the copy changes the original too.</li><li><strong>Deep copy:</strong> every nested object is also copied recursively. The original and the copy are completely independent.</li></ul><p><code>Object.clone()</code> does a shallow copy. Copy constructors let you choose per field.</p><hr><h2 id="choosing-between-them-—-the-one-question-test" tabindex="-1">Choosing between them — the one-question test <a class="header-anchor" href="#choosing-between-them-—-the-one-question-test" aria-label="Permalink to &quot;Choosing between them — the one-question test&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Pattern</th></tr></thead><tbody><tr><td>Do I need exactly one instance globally?</td><td>Singleton</td></tr><tr><td>Do I need an object but want to decide the concrete type elsewhere?</td><td>Factory Method</td></tr><tr><td>Do I need a set of objects that must match each other?</td><td>Abstract Factory</td></tr><tr><td>Does the object have many fields, some optional, and I want immutability?</td><td>Builder</td></tr><tr><td>Do I want a named constructor, caching, or to hide the concrete type?</td><td>Static Factory Method</td></tr><tr><td>Is construction expensive and I already have a good template?</td><td>Prototype</td></tr></tbody></table><hr><h2 id="the-trap-each-one-hides" tabindex="-1">The trap each one hides <a class="header-anchor" href="#the-trap-each-one-hides" aria-label="Permalink to &quot;The trap each one hides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pattern</th><th>Common mistake</th></tr></thead><tbody><tr><td>Singleton</td><td>Using it everywhere — it&#39;s a hidden global that breaks testability</td></tr><tr><td>Factory Method</td><td>Adding it when a plain constructor would do; not every <code>new</code> needs a factory</td></tr><tr><td>Abstract Factory</td><td>Stuffing behaviour (e.g., <code>furnishRoom</code>) into the factory — consumption belongs to the caller</td></tr><tr><td>Builder</td><td>Skipping required-field enforcement — if a field is mandatory, it goes in the builder&#39;s constructor, not as a setter</td></tr><tr><td>Static Factory</td><td>Calling <code>JobOffer.builder()</code> a &quot;static factory method&quot; — it returns a <code>Builder</code>, not a <code>JobOffer</code>; that&#39;s not the EJ definition</td></tr><tr><td>Prototype</td><td>Using <code>clone()</code> and assuming deep copy — it&#39;s shallow unless you override everything</td></tr></tbody></table>',48)])])}const y=t(n,[["render",c]]);export{u as __pageData,y as default};
